package mx.com.mesaregia.logistica.application.service.impl;
import mx.com.mesaregia.logistica.api.request.ToleranciaUpdateRequest; import mx.com.mesaregia.logistica.api.response.ToleranciaResponse; import mx.com.mesaregia.logistica.application.service.ToleranciaService; import mx.com.mesaregia.logistica.domain.enums.*; import mx.com.mesaregia.logistica.exception.*; import mx.com.mesaregia.logistica.mapper.LogisticaMapper; import mx.com.mesaregia.logistica.repository.ToleranciaRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ToleranciaServiceImpl implements ToleranciaService {private final ToleranciaRepository repo;private final LogisticaMapper map;public ToleranciaServiceImpl(ToleranciaRepository r,LogisticaMapper m){repo=r;map=m;}
 @Transactional(readOnly=true) public List<ToleranciaResponse> listar(){return repo.findAllByActivoTrueOrderByIdAsc().stream().map(map::tolerancia).toList();}
 @Transactional public ToleranciaResponse actualizar(CodigoEtapa c,ToleranciaUpdateRequest r){var t=repo.findByCodigoEtapa(c).orElseThrow(()->new ResourceNotFoundException("Tolerancia no encontrada"));ServiceSupport.version(t.getVersion(),r.version());if(t.getUnidad()!=UnidadTolerancia.MINUTOS||!t.isAplica())throw new BusinessRuleException("Los traslados se controlan por fecha/hora y no admiten tolerancia editable en minutos");t.setMinutos(r.minutos());return map.tolerancia(repo.saveAndFlush(t));}
}
